module Monopole_Magnet_Calculator(\n    input clk,\n    input rst_n,\n    input start,\n    input [7:0] grid_0,\n    input [7:0] grid_1,\n    input [7:0] grid_2,\n    input [7:0] grid_3,\n    input [7:0] grid_4,\n    input [7:0] grid_5,\n    input [7:0] grid_6,\n    input [7:0] grid_7,\n    output reg [15:0] result,\n    output reg done\n);\n\n    // State definitions\n    localparam [2:0] IDLE              = 3'd0;\n    localparam [2:0] ROW_CHECK         = 3'd1;\n    localparam [2:0] COL_CHECK         = 3'd2;\n    localparam [2:0] CONSISTENCY_CHECK = 3'd3;\n    localparam [2:0] COMPONENT_COUNT   = 3'd4;\n    localparam [2:0] DONE_STATE        = 3'd5;\n    localparam [2:0] ERROR_STATE       = 3'd6;\n\n    reg [2:0] state, next_state;\n    reg [7:0] grid [0:7];  // [row][col] - grid_0 is row0\n    reg [7:0] visited [0:7];\n    reg [3:0] row_ptr;     // Row counter\n    reg [3:0] col_ptr;     // Column counter\n    reg invalid_rows_cols;\n    reg [3:0] empty_rows;\n    reg [3:0] empty_cols;\n    reg [15:0] component_count;\n    reg [7:0] row_cache;\n    reg [7:0] col_cache;\n    reg [2:0] check_phase;\n    reg [7:0] col_data;\n    reg in_transition;\n    reg component_found;\n    reg [7:0] current_row;\n    integer i;\n\n    // Initialize grid array\n    always @(*) begin\n        grid[0] = grid_0;\n        grid[1] = grid_1;\n        grid[2] = grid_2;\n        grid[3] = grid_3;\n        grid[4] = grid_4;\n        grid[5] = grid_5;\n        grid[6] = grid_6;\n        grid[7] = grid_7;\n    end\n\n    // Main FSM\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            result <= 16'd0;\n            done <= 1'b0;\n            row_ptr <= 4'd0;\n            col_ptr <= 4'd0;\n            invalid_rows_cols <= 1'b0;\n            empty_rows <= 4'd0;\n            empty_cols <= 4'd0;\n            component_count <= 16'd0;\n            check_phase <= 3'd0;\n            in_transition <= 1'b0;\n            component_found <= 1'b0;\n\n            // Clear visited array\n            for (i = 0; i < 8; i = i + 1) begin\n                visited[i] <= 8'd0;\n            end\n        end else begin\n            done <= 1'b0;  // Done clears automatically\n            case (state)\n                IDLE: begin\n                    if (start) begin\n                        state <= ROW_CHECK;\n                        row_ptr <= 4'd0;\n                        empty_rows <= 4'd0;\n                        invalid_rows_cols <= 1'b0;\n                    end\n                end\n\n                ROW_CHECK: begin\n                    // Check current row contiguity\n                    current_row = grid[row_ptr];\n                    reg [3:0] transition_count;\n                    transition_count = 4'd0;\n                    col_cache = 8'd0;\n\n                    // Detect transitions (0->1 or 1->0)\n                    for (i = 0; i < 8; i = i + 1) begin\n                        if (current_row[i] ^ (i > 0 ? current_row[i-1] : 1'b0)) begin\n                            transition_count = transition_count + 4'd1;\n                        end\n                    end\n\n                    // Invalid if >2 transitions but not empty\n                    if (current_row != 8'd0 && transition_count > 4'd2) begin\n                        invalid_rows_cols <= 1'b1;\n                    end\n\n                    // Count empty rows\n                    if (current_row == 8'd0) begin\n                        empty_rows <= empty_rows + 4'd1;\n                    end\n\n                    if (row_ptr == 4'd7) begin\n                        state <= COL_CHECK;\n                        row_ptr <= 4'd0;\n                    end else begin\n                        row_ptr <= row_ptr + 4'd1;\n                    end\n                end\n\n                COL_CHECK: begin\n                    // Assemble current column\n                    col_data = {grid[0][col_ptr], grid[1][col_ptr], grid[2][col_ptr],\n                               grid[3][col_ptr], grid[4][col_ptr], grid[5][col_ptr],\n                               grid[6][col_ptr], grid[7][col_ptr]};\n\n                    // Detect transitions\n                    reg [3:0] trans_count;\n                    trans_count = 4'd0;\n                    for (i = 0; i < 8; i = i + 1) begin\n                        if (col_data[i] ^ (i > 0 ? col_data[i-1] : 1'b0)) begin\n                            trans_count = trans_count + 4'd1;\n                        end\n                    end\n\n                    // Validate column\n                    if (col_data != 8'd0 && trans_count > 4'd2) begin\n                        invalid_rows_cols <= 1'b1;\n                    end\n\n                    // Count empty columns\n                    if (col_data == 8'd0) begin\n                        empty_cols <= empty_cols + 4'd1;\n                    end\n\n                    if (col_ptr == 4'd7) begin\n                        if (invalid_rows_cols) begin\n                            state <= ERROR_STATE;\n                        end else begin\n                            state <= CONSISTENCY_CHECK;\n                        end\n                        col_ptr <= 4'd0;\n                    end else begin\n                        col_ptr <= col_ptr + 4'd1;\n                    end\n                end\n\n                CONSISTENCY_CHECK: begin\n                    // Check condition: (empty_rows !=0 ^ empty_cols !=0) must be false\n                    if ((empty_rows != 4'd0) ^ (empty_cols != 4'd0)) begin\n                        state <= ERROR_STATE;\n                    end else begin\n                        state <= COMPONENT_COUNT;\n                        row_ptr <= 4'd0;\n                        component_count <= 16'd0;\n                        // Clear visited array\n                        for (i = 0; i < 8; i = i + 1) begin\n                            visited[i] <= 8'd0;\n                        end\n                    end\n                end\n\n                COMPONENT_COUNT: begin\n                    // If current cell is black && not visited, trigger BFS\n                    if (grid[row_ptr][col_ptr] && !visited[row_ptr][col_ptr]) begin\n                        visited[row_ptr][col_ptr] <= 1'b1;\n                        component_count <= component_count + 16'd1;\n                        in_transition <= 1'b1;\n                        component_found <= 1'b1;\n                    end\n\n                    if (!in_transition) begin\n                        if (col_ptr == 4'd7) begin\n                            if (row_ptr == 4'd7) begin\n                                state <= DONE_STATE;\n                            end else begin\n                                row_ptr <= row_ptr + 4'd1;\n                                col_ptr <= 4'd0;\n                            end\n                        end else begin\n                            col_ptr <= col_ptr + 4'd1;\n                        end\n                    end else begin\n                        // Simplified BFS marking logic (iterative part)\n                        component_found <= 1'b0;\n                        for (i = 0; i < 8; i = i + 1) begin\n                            // Logic to mark adjacent cells (simplified)\n                            if (row_ptr < 4'd7 && grid[row_ptr+1][col_ptr] && !visited[row_ptr+1][col_ptr]) begin\n                                visited[row_ptr+1][col_ptr] <= 1'b1;\n                            end\n                            if (row_ptr > 4'd0 && grid[row_ptr-1][col_ptr] && !visited[row_ptr-1][col_ptr]) begin\n                                visited[row_ptr-1][col_ptr] <= 1'b1;\n                            end\n                            if (col_ptr < 4'd7 && grid[row_ptr][col_ptr+1] && !visited[row_ptr][col_ptr+1]) begin\n                                visited[row_ptr][col_ptr+1] <= 1'b1;\n                            end\n                            if (col_ptr > 4'd0 && grid[row_ptr][col_ptr-1] && !visited[row_ptr][col_ptr-1]) begin\n                                visited[row_ptr][col_ptr-1] <= 1'b1;\n                            end\n                        end\n                        in_transition <= 1'b0;\n                    end\n                end\n\n                DONE_STATE: begin\n                    result <= component_count;\n                    done <= 1'b1;\n                    state <= IDLE;\n                end\n\n                ERROR_STATE: begin\n                    result <= 16'hFFFF;\n                    done <= 1'b1;\n                    state <= IDLE;\n                end\n\n                default: state <= IDLE;\n            endcase\n        end\n    end\nendmodule